LINES = [{'id': 'rule', 'text': 'In this town, every lie makes you shrink one inch. Watch my brother Max say he brushed his teeth.'}, {'id': 'week', 'text': "He says it every night. Seven nights, seven lies, seven inches. Now he can't even reach the sink."}, {'id': 'nora', 'text': "I'm Nora. I've told exactly one lie in my whole life, and I still miss that inch."}, {'id': 'gus', 'text': 'Honest people do great here. Gus the baker says his muffins taste like socks. Still full size!'}, {'id': 'jade', 'text': "But Jade told twenty friends she loved their haircut. Now she's shorter than a fire hydrant."}, {'id': 'gnome', 'text': 'Tiny is no fun. Jade gets skipped in line, stepped on, and mistaken for a garden gnome.'}, {'id': 'idea', 'text': 'Then rich Mr. Snell had an evil idea. Tiny people can fit under a vault door.'}, {'id': 'unicorn', 'text': "So he lied on purpose. 'I'm a unicorn! I love broccoli! I'm very humble!'"}, {'id': 'taxes', 'text': "'I pay my taxes!' Thirty lies later, Mr. Snell was the size of a hamster."}, {'id': 'vault', 'text': 'He tiptoed under the vault door, and a thousand gold bars disappeared, one tiny trip at a time.'}, {'id': 'guards', 'text': "Otis the guard yelled, 'I'm not scared!' Ms Penny said, 'It's fine!' Two lies. Down they went."}, {'id': 'chaos', 'text': 'Then everyone panicked and lied to blame each other, until the whole bank was knee high.'}, {'id': 'confess', 'text': "I was the only tall one left. So I confessed my one lie. Max's drawing looked like a potato."}, {'id': 'grow', 'text': 'And I grew my inch back! Confessing undoes a lie. Nobody in town had ever tried it.'}, {'id': 'pop', 'text': 'So everyone confessed. Otis is scared of hamsters. Ms Penny hates coins. Pop, pop, pop!'}, {'id': 'snell', 'text': 'Tiny Snell needed his full size to carry the gold. So he confessed everything, even stealing it.'}, {'id': 'busted', 'text': 'He popped back to normal right in front of Otis, holding a thousand gold bars. Busted!'}, {'id': 'home', 'text': 'Back home, Max was still tiny. So I told him the secret. Confessing gives inches back.'}, {'id': 'teeth', 'text': 'Max confessed. He has never brushed his teeth. Not once. Ever. Mom fainted.'}, {'id': 'end', 'text': "So my brother is tall again. His breath, though? Still terrible. And that's no lie."}]
TITLES = [('@rule+0.4', '@rule+2.0', 'LIES'), ('@chaos+0.4', '@chaos.end+0.3', 'CHAOS'), ('@grow+0.4', '@grow.end+0.3', 'CONFESS!'), ('@busted+0.4', '@busted.end+0.3', 'BUSTED'), ('@end+0.4', '@end.end+0.3', 'NO LIE')]
